async void Fire() { await Task.Delay(100); throw new InvalidOperationException(); }

try { Fire(); }      // 1) Fire reached the await and returned
catch { }            // 2) the try is over — nothing to catch here
Console.ReadLine();  // 3) 100 ms later the continuation throws on the pool
                     // 4) the builder throws it on a pool thread — the process crashes

