static async void Fire() { await Task.Delay(100); throw new InvalidOperationException(); }

static void Main()
{
    try { Fire(); }
    catch (InvalidOperationException) { Console.WriteLine("caught"); }
    Console.ReadLine();   // the program waits for input
}

