static async void Fire(string? path)
{
    if (path is null) throw new ArgumentNullException(nameof(path));
    await File.WriteAllTextAsync(path, "x");
}

try { Fire(null); }
catch (ArgumentNullException) { Console.WriteLine("caught"); }
Console.ReadLine();

