async Task RunSafeAsync(Func<Task> work)
{
    try { await work(); }                                   // wait inside the wrapper
    catch (Exception e) { log.LogError(e, "background task failed"); }
}

_ = RunSafeAsync(() => SendEmailAsync(user));   // not waiting on purpose; the error gets logged
